<?php require_once __DIR__.'/functions.php'; require_once __DIR__.'/app_init.php'; $pdo=dogvive_db(); $uid=dogvive_user_id();
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['cancelar'])){ $id=(int)$_POST['cancelar']; $q=$pdo->prepare("UPDATE reserva SET Estado='Cancelada' WHERE id_reserva=? AND (id_usuario=? OR id_entrenador=?) AND Estado IN ('Pendiente','Confirmada')"); $q->execute([$id,$uid,$uid]); dogvive_flash('success',$q->rowCount()?'Reserva cancelada.':'No se pudo cancelar esa reserva.'); header('Location: '.base_url().'/reservas.php'); exit; }
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['estado_nuevo'])&&current_role()==='Entrenador'){ $id=(int)($_POST['id_reserva']??0); $state=(string)$_POST['estado_nuevo']; if(in_array($state,['Confirmada','Completada','Cancelada'],true)){ $q=$pdo->prepare("UPDATE reserva SET Estado=? WHERE id_reserva=? AND id_entrenador=? AND Estado IN ('Pendiente','Confirmada')"); $q->execute([$state,$id,$uid]); if($q->rowCount()){ $n=$pdo->prepare('SELECT id_usuario FROM reserva WHERE id_reserva=?');$n->execute([$id]);$owner=(int)$n->fetchColumn();dogvive_notice($pdo,$owner,'Reserva','El estado de tu reserva #'.$id.' cambió a '.$state.'.','reservas.php');dogvive_flash('success','Estado de reserva actualizado.');}else dogvive_flash('error','No se pudo actualizar esa reserva.'); } header('Location: '.base_url().'/reservas.php'); exit; }
start_app('Mis reservas','reservas'); page_wrap_start('Mis reservas','Consulta solicitudes, horarios y estados.'); $success=dogvive_flash('success'); if($success) echo '<div class="notice">'.e($success).'</div>';
if(current_role()==='Entrenador'){$q=$pdo->prepare('SELECT r.*,s.Nombre AS servicio,m.Nombre AS mascota,u.Nombre AS propietario,u.Apellido AS apellido FROM reserva r LEFT JOIN servicio s ON s.id_servicio=r.id_servicio LEFT JOIN mascota m ON m.id_mascota=r.id_mascota LEFT JOIN usuario u ON u.id_usuario=r.id_usuario WHERE r.id_entrenador=? ORDER BY r.Fecha DESC,r.Hora DESC');$q->execute([$uid]);}else{$q=$pdo->prepare('SELECT r.*,s.Nombre AS servicio,m.Nombre AS mascota,t.Nombre AS entrenador,t.Apellido AS entrenador_apellido FROM reserva r LEFT JOIN servicio s ON s.id_servicio=r.id_servicio LEFT JOIN mascota m ON m.id_mascota=r.id_mascota LEFT JOIN usuario t ON t.id_usuario=r.id_entrenador WHERE r.id_usuario=? ORDER BY r.Fecha DESC,r.Hora DESC');$q->execute([$uid]);}$rows=$q->fetchAll();
if(!$rows) echo '<div class="card"><h3>No tienes reservas todavía</h3><p class="muted">Cuando solicites una sesión, aparecerá aquí.</p>'.(current_role()==='Propietario'?btn('Solicitar servicio',page_url('solicitud-servicio'),'btn-primary'):'').'</div>';
else {echo '<div class="card"><div class="booking-list">';foreach($rows as $r){$state=(string)($r['Estado']??'Pendiente');$person=current_role()==='Entrenador'?trim(($r['propietario']??'').' '.($r['apellido']??'')):trim(($r['entrenador']??'Por asignar').' '.($r['entrenador_apellido']??''));echo '<div class="booking-item"><div class="grow"><strong>'.e((string)($r['servicio']??'Servicio')).' · '.e((string)($r['mascota']??'Mascota')).'</strong><small class="muted">'.e($person).'</small><small class="muted">📅 '.e((string)$r['Fecha']).' · ⏰ '.e(substr((string)$r['Hora'],0,5)).'</small><small class="muted">'.e((string)($r['Descripcion']??'')).'</small><span class="badge">'.e($state).'</span></div>';if(current_role()==='Entrenador' && in_array($state,['Pendiente','Confirmada'],true)){echo '<form method="post"><input type="hidden" name="id_reserva" value="'.(int)$r['id_reserva'].'">';if($state==='Pendiente')echo '<button class="btn btn-primary" name="estado_nuevo" value="Confirmada">Confirmar</button>';else echo '<button class="btn btn-primary" name="estado_nuevo" value="Completada">Marcar completada</button>';echo '<button class="btn btn-secondary" name="estado_nuevo" value="Cancelada">Cancelar</button></form>';} elseif(current_role()==='Propietario' && in_array($state,['Pendiente','Confirmada'],true)){echo '<form method="post"><button class="btn btn-secondary" type="submit" name="cancelar" value="'.(int)$r['id_reserva'].'">Cancelar</button></form>'; }if($state==='Completada'&&current_role()==='Propietario')echo btn('Calificar',base_url().'/calificar.php?id='.(int)$r['id_reserva'],'btn-secondary');echo '</div>'; } echo '</div></div>';}
page_wrap_end();end_app();
